-- GERADO POR scripts/generate-layout-seed.cjs — não editar à mão.
-- Catálogo interno (§8). `is_builtin` marca o que veio da biblioteca do produto;
-- o administrador pode desativar uma linha mudando `status`, sem perder a origem.

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, structure = EXCLUDED.structure, updated_at = NOW();

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, text_limits = EXCLUDED.text_limits, default_style = EXCLUDED.default_style, updated_at = NOW();

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, rules = EXCLUDED.rules, typography = EXCLUDED.typography, updated_at = NOW();

